INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Paketweiterleitung die einzige Funktion eines Gateways?', 2, '[{"text": "Nein", "correct": true, "because": "Auch NAT oder Firewall möglich"}, {"text": "Ja", "correct": false, "because": "Funktionen sind breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Gateway bei der Paketweiterleitung?', 3, '[{"text": "Routing zwischen Netzen", "correct": true, "because": "Verbindet Subnetze"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht primäre Aufgabe"}, {"text": "Adresszuweisung", "correct": false, "because": "DHCP-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse sind bei der Paketweiterleitung beteiligt?', 5, '[{"text": "Routing-Tabellenprüfung", "correct": true, "because": "Bestimmt Zielnetz"}, {"text": "Hop-Limit-Anpassung", "correct": true, "because": "Vermeidet Schleifen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht Gateway-Aufgabe"}, {"text": "DNS-Auflösung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Gateway leitet Pakete nur lokal weiter. b) Es nutzt Routing-Protokolle.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, Routing ist extern"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Paketweiterleitung?', 4, '[{"text": "Ziel-IP", "correct": false, "because": "Bestimmt Routing"}, {"text": "Routing-Tabelle", "correct": false, "because": "Leitet Entscheidung"}, {"text": "Dateninhalt", "correct": true, "because": "Gateway liest Payload nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Gateway Pakete ohne Routing-Tabelle weiterleitet?', 2, '[{"text": "Nein", "correct": true, "because": "Tabelle ist essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Tabelle kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll ist für die Paketweiterleitung entscheidend?', 3, '[{"text": "IP", "correct": true, "because": "Definiert Adressierung"}, {"text": "TCP", "correct": false, "because": "Transportebene"}, {"text": "HTTP", "correct": false, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen übernimmt ein Gateway bei Paketen?', 5, '[{"text": "Netzwerkübergang", "correct": true, "because": "Verbindet Subnetze"}, {"text": "Hop-Limit-Reduktion", "correct": true, "because": "Begrenzt Weiterleitung"}, {"text": "Paketverschlüsselung", "correct": false, "because": "Nicht Standard"}, {"text": "Bandbreitensteuerung", "correct": false, "because": "QoS-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Paketweiterleitung braucht eine IP. b) Sie passiert nur auf Schicht 2. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 3, nicht 2"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Paketweiterleitung?', 4, '[{"text": "Zieladresse", "correct": false, "because": "Routing-Grundlage"}, {"text": "Routing-Information", "correct": false, "because": "Leitet Entscheidung"}, {"text": "Webserver", "correct": true, "because": "Nicht Routing-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Leitet ein Gateway auch lokale Pakete weiter?', 2, '[{"text": "Nein", "correct": true, "because": "Nur zwischen Netzen"}, {"text": "Ja", "correct": false, "because": "Lokales ist Switch-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information ist für die Weiterleitung entscheidend?', 4, '[{"text": "Ziel-IP", "correct": true, "because": "Bestimmt Routing-Pfad"}, {"text": "Quell-Port", "correct": false, "because": "Transportebene"}, {"text": "Datenlänge", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Paketweiterleitung immer NAT braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "NAT ist optional"}, {"text": "Ja", "correct": false, "because": "Routing unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Paketweiterleitung?', 3, '[{"text": "Routing-Tabelle", "correct": true, "because": "Definiert Ziel"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "Protokolltyp", "correct": false, "because": "Routing-unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Paketweiterleitung nutzt IP. b) Sie passiert auf Schicht 4.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 3, nicht 4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Paketweiterleitung?', 5, '[{"text": "Netzwerkverbindung", "correct": true, "because": "Übergang ermöglicht"}, {"text": "Effiziente Routen", "correct": true, "because": "Optimiert Pfade"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Paketweiterleitung unwichtig?', 3, '[{"text": "Zielnetz", "correct": false, "because": "Routing-Ziel"}, {"text": "Hop-Limit", "correct": false, "because": "Begrenzt Schleifen"}, {"text": "Anwendungsdaten", "correct": true, "because": "Payload wird nicht geprüft"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Passiert Paketweiterleitung ohne IP?', 3, '[{"text": "Nein", "correct": true, "because": "IP ist Grundlage"}, {"text": "Ja", "correct": false, "because": "IP-Adressierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Gateway Pakete verändert?', 2, '[{"text": "Ja", "correct": true, "because": "Hop-Limit wird reduziert"}, {"text": "Nein", "correct": false, "because": "Anpassung erfolgt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente steuert die Weiterleitung?', 4, '[{"text": "Routing-Tabelle", "correct": true, "because": "Definiert Pfad"}, {"text": "Firewall-Regeln", "correct": false, "because": "Filtert, nicht leitet"}, {"text": "NAT-Tabelle", "correct": false, "because": "Optional"}]');
